#include <stdio.h>

struct record {
    int id;
    char name[8];
};

int main(void)
{
    struct record r = { 1, "hero" };
    FILE *fp = fopen("save.bin", "wb");
    fwrite(&r, sizeof(r), 1, fp);
    fclose(fp);

    struct record loaded;
    fp = fopen("save.bin", "rb");
    size_t n = fread(&loaded, sizeof(loaded), 1, fp);
    fclose(fp);

    if (n == 1)
        printf("id=%d name=%s\n", loaded.id, loaded.name);
    return 0;
}

